import Header from './Header.js';
import Clock from './Clock.js';
import Pomobtn from './Pomobtn.js';
import Timer from './Timer.js';
import Start from './Start.js';
import Description from './Description.js';
import TaskManager from './TaskManager.js';
import { BrowserRouter as Router } from 'react-router-dom';
import React, { useState, useEffect } from 'react';
import useFunctions from './hooks/useAppFunctions.js';

function App() {
  const {
    pomoInput,
    setPomoInput,
    longInput,
    setLongInput,
    shortInput,
    setShortInput,
    color,
    setColor,
    backgroundPicture,
    setBackgroundPicture,
    time,
    formatTime,
    handleStart,
    handlePause,
    handleReset,
    handleButtonClick,
  } = useFunctions();

  const isLoggedIn = false;

  return (
    <Router>

      <div className="App">
        <div className="contentWrap">
          <Header
            pomoInput={pomoInput}
            setPomoInput={setPomoInput}
            longInput={longInput}
            setLongInput={setLongInput}
            shortInput={shortInput}
            setShortInput={setShortInput}
            color={color}
            setColor={setColor}
            backgroundPicture={backgroundPicture}
            setBackgroundPicture={setBackgroundPicture}
            isLoggedIn={isLoggedIn}
          />

          <div className="contentContainer">
            <Clock />

            <Pomobtn
              /*creates props to be passed in with onClick function*/
              pomoTime={`${pomoInput}:00`}
              longTime={`${longInput}:00`}
              shortTime={`${shortInput}:00`}
              onClick={handleButtonClick}
            />

            <Timer time={formatTime(time)} />

            <Start
              onStart={handleStart}
              onPause={handlePause}
              onReset={handleReset}
            />
          </div>
        </div>
        <TaskManager />
        <Description />
      </div>
    </Router>
  );
}

export default App;
